package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.graphics.Typeface;
import android.text.*;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Reads the Steam ID stored on the current account; no library import or edits. */
final class SteamDataView extends ScrollView {
 private final LinearLayout body,list;private final TextView state;private final EditText search;private final Button more,refresh;private JSONArray games=new JSONArray(),recent=new JSONArray();private int mode,limit=40;private boolean loading,connected;
 SteamDataView(Context c){super(c);setFillViewport(true);setVerticalScrollBarEnabled(false);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(16),dp(18),dp(24));addView(body);TextView heading=text("Biblioteca Steam",25,0xfff3f4f8);heading.setTypeface(null,Typeface.BOLD);body.addView(heading);state=text("Carregando sua Steam…",13,0xff9ca9b8);body.addView(state);search=new EditText(c);search.setHint("Buscar na Steam");search.setSingleLine(true);AppStyle.input(search);body.addView(search);Spinner filters=new Spinner(c);filters.setAdapter(new ArrayAdapter<>(c,android.R.layout.simple_spinner_dropdown_item,new String[]{"Mais jogados","Nome A–Z","Nunca jogados","Jogados recentemente"}));body.addView(filters,new LinearLayout.LayoutParams(-1,dp(48)));list=new LinearLayout(c);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);more=new Button(c);more.setText("Mostrar mais");AppStyle.button(more,false);more.setOnClickListener(v->{limit+=40;render();});more.setVisibility(GONE);body.addView(more);refresh=new Button(c);refresh.setText("Atualizar Steam");AppStyle.button(refresh,false);refresh.setOnClickListener(v->load());body.addView(refresh);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){limit=40;if(!loading)render();}public void afterTextChanged(Editable e){}});filters.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,android.view.View v,int pos,long id){mode=pos;limit=40;if(!loading)render();}public void onNothingSelected(AdapterView<?> p){}});load();}
 private void load(){if(loading)return;loading=true;refresh.setEnabled(false);more.setVisibility(GONE);state.setText("Consultando sua biblioteca Steam…");new AccountRepository(getContext()).steam((rows,error)->{loading=false;refresh.setEnabled(true);if(error!=null){state.setText(error);return;}JSONObject data=rows.optJSONObject(0);connected=data!=null&&data.optBoolean("connected");if(!connected){list.removeAllViews();state.setText("Esta conta ainda não tem uma Steam vinculada. Conecte sua Steam nas Configurações do aplicativo.");return;}games=data.optJSONArray("jogos");recent=data.optJSONArray("recentes");if(games==null)games=new JSONArray();if(recent==null)recent=new JSONArray();limit=40;render();});}
 private void render(){if(!connected)return;list.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);List<JSONObject> filtered=new ArrayList<>();JSONArray source=mode==3?recent:games;double totalHours=0;for(int i=0;i<games.length();i++){JSONObject g=games.optJSONObject(i);if(g!=null)totalHours+=Math.max(0,g.optDouble("horas",0));}for(int i=0;i<source.length();i++){JSONObject g=source.optJSONObject(i);if(g==null||!g.optString("nome","").toLowerCase(Locale.ROOT).contains(q)||mode==2&&g.optDouble("horas",0)>0)continue;filtered.add(g);}if(mode==1)Collections.sort(filtered,(a,b)->a.optString("nome","").compareToIgnoreCase(b.optString("nome","")));else if(mode!=3)Collections.sort(filtered,(a,b)->Double.compare(b.optDouble("horas",0),a.optDouble("horas",0)));
  state.setText(games.length()==0?"Nenhum jogo retornado. A Steam precisa permitir a leitura pública dos detalhes de jogos.":games.length()+" jogos • "+Math.round(totalHours)+" h • "+filtered.size()+" no filtro");
  for(int i=0;i<Math.min(limit,filtered.size());i++){JSONObject g=filtered.get(i);LinearLayout card=new LinearLayout(getContext());card.setOrientation(LinearLayout.HORIZONTAL);card.setGravity(android.view.Gravity.CENTER_VERTICAL);card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(AppStyle.shape(card,0xff1c242f,16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(10),0,0);list.addView(card,lp);ImageView image=new ImageView(getContext());image.setBackground(AppStyle.shape(image,0xff303449,10));image.setClipToOutline(true);image.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(image,new LinearLayout.LayoutParams(dp(82),dp(106)));AccountImageLoader.load(image,"",g.optString("appid",""));LinearLayout info=new LinearLayout(getContext());info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(14),0,0,0);card.addView(info,new LinearLayout.LayoutParams(0,-2,1));TextView name=text(g.optString("nome","Jogo"),16,0xfff3f4f8);name.setTypeface(null,Typeface.BOLD);info.addView(name);info.addView(text(g.optString("horas","0")+" horas jogadas",13,0xffb7a6ff));if(mode==3)info.addView(text(g.optString("horasRecentes","0")+" h nas últimas 2 semanas",12,0xff9ca9b8));}
  if(filtered.isEmpty()&&games.length()>0)list.addView(text("Nenhum jogo corresponde ao filtro.",14,0xff9ca9b8));more.setVisibility(filtered.size()>limit?VISIBLE:GONE);
 }
 private TextView text(String s,int size,int color){TextView v=new TextView(getContext());v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(6),0,dp(6));return v;}
 private int dp(int n){return AppStyle.dp(this,n);}
}
